( select A.cdate,A.portfolioId,A.portfolioName,A.finprodType2,A.type5,A.finprodMarketId,A.finprodAbbr,A.marketValue, CASE WHEN A.finprodType2 IN ('F08', 'F09', 'F16') THEN NULL ELSE A.dscCostAmt END dscCostAmt, A.shareAmt, A.tdyIntincexp, round((nvl(A.marketValue, 0) + nvl(A.tdyIntincexp, 0)) / B.typeMarketValue, 4) * 100 as tdyAmtRation, (round((nvl(A.marketValue, 0) + nvl(A.tdyIntincexp, 0)) / B.typeMarketValue, 4) - nvl(C.ystAmtRation, 0)) * 100 as ystAmtRation, (round((nvl(A.marketValue, 0) + nvl(A.tdyIntincexp, 0)) / B.typeMarketValue, 4) - nvl(D.monthAmtRation, 0)) * 100 as monthAmtRation, (round((nvl(A.marketValue, 0) + nvl(A.tdyIntincexp, 0)) / B.typeMarketValue, 4) - nvl(F.yearAmtRation, 0)) * 100 as yearAmtRation from ( select psv.CDATE as cdate,psv.PORTFOLIO_ID as portfolioId,pp.PORTFOLIO_NAME as portfolioName, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*psv.TDY_INTINCEXP when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.TDY_INTINCEXP when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*psv.TDY_INTINCEXP else psv.TDY_INTINCEXP end as tdyIntincexp, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) else (NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) end as marketValue, psv.SHARE_AMT as shareAmt, fpt.TYPE_8 as finprodType2, nvl(fp.FINPROD_MARKET_ID,psv.FINPROD_ID) as finprodMarketId, NVL(fp.FINPROD_ID,psv.FINPROD_ID) AS finprodId, nvl(fp.FINPROD_ABBR, fp.FINPROD_NAME) as finprodAbbr, decode(fpt.TYPE_8,'F07',fpt.TYPE_7,'F10',fpt.TYPE_7,fpt.TYPE_6) as type5 from PTL_SEC_VALUTION psv left join FIN_PRODUCT fp on psv.FINPROD_ID=fp.FINPROD_ID left join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID left join FIN_PRODUCT_ADD fpa ON nvl(pp.PARENT_PORTFOLIO_ID,pp.PORTFOLIO_ID)=fpa.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT FP1 ON FPA.FINPROD_ID = FP1.FINPROD_ID inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null where FP1.FINPROD_TYPE2 = 'F16'
AND psv.PORTFOLIO_ID IN
#{item}
