group by psv.CDATE,psv.PORTFOLIO_ID ) B on A.portfolioId=B.portfolioId and A.cdate=B.cdate and B.typeMarketValue!=0 left join( select AA.cdate,AA.portfolioId,AA.finprodType2,AA.finprodId,round((nvl(AA.marketValue, 0) + nvl(AA.tdyIntincexp, 0)) / BB.typeMarketValue, 4) as ystAmtRation from( select psv.CDATE as cdate, psv.PORTFOLIO_ID as portfolioId, psv.FINPROD_ID AS finprodId, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) else (nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) end ) as marketValue, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_INTINCEXP,0)) else (nvl(psv.TDY_INTINCEXP,0)) end ) as tdyIntincexp, fpt.TYPE_8 as finprodType2 from PTL_SEC_VALUTION psv
