select.if:
select cdate,null portfolioId,null portfolioName,finprodType2,null type5,null finprodMarketId,null finprodAbbr, sum(marketValue) marketValue, CASE WHEN finprodType2 IN ('F08', 'F09', 'F16') THEN NULL ELSE sum(dscCostAmt) END dscCostAmt, sum(shareAmt) shareAmt, sum(tdyIntincexp) tdyIntincexp, sum(tdyAmtRation) tdyAmtRation, sum(ystAmtRation) ystAmtRation, sum(monthAmtRation) monthAmtRation, sum(yearAmtRation) yearAmtRation, '02' hasChildren, CONCAT(CONCAT(portfolioId,'_'),nvl(finprodType2,'null')) childInfo, CONCAT(nvl(portfolioId,'null'),'') parentInfo, finprodType2 as otherFinprodType2, portfolioName otherPortfolioName from
CONCAT(nvl(portfolioId,'null'),'') = #{parentId}
group by cdate,portfolioId,portfolioName,finprodType2 union all select cdate,null portfolioId,null portfolioName,null finprodType2, type5, case when finprodType2 IN ('F14', 'F15') THEN NULL ELSE finprodMarketId END finprodMarketId,/*远期掉期不显示资产名称和代码*/ finprodAbbr, sum(marketValue) marketValue, sum(dscCostAmt) dscCostAmt, sum(shareAmt) shareAmt, sum(tdyIntincexp) tdyIntincexp, sum(tdyAmtRation) tdyAmtRation, sum(ystAmtRation) ystAmtRation, sum(monthAmtRation) monthAmtRation, sum(yearAmtRation) yearAmtRation, '01' hasChildren, CONCAT(CONCAT(nvl(portfolioId,'null'),'_'),CONCAT(CONCAT(nvl(finprodType2,'null'),'_'),type5)) childInfo, CONCAT(CONCAT(portfolioId,'_'),nvl(finprodType2,'null')) parentInfo, finprodType2 as otherFinprodType2, portfolioName otherPortfolioName from
CONCAT(CONCAT(portfolioId,'_'),nvl(finprodType2,'null')) = #{parentId}
group by cdate,portfolioId,portfolioName,finprodType2,type5,finprodMarketId,finprodAbbr

mapper.select:
select AA.finprodType2, sum(AA.marketValue) as marketValue, CASE WHEN AA.finprodType2 IN ('F08', 'F09', 'F16') THEN NULL ELSE sum(AA.dscCostAmt) END as dscCostAmt, sum(AA.amtRation) as amtRation, sum(nvl(AA.tdyIntincexp, 0)) as tdyIntincexp from (select A.finprodType2,A.marketValue,A.dscCostAmt,A.tdyIntincexp, (nvl(A.marketValue,0)+nvl(A.tdyIntincexp,0))*100/B.typeMarketValue as amtRation from ( select psv.CDATE as cdate,fpt.TYPE_8 as finprodType2, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*psv.TDY_INTINCEXP when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.TDY_INTINCEXP when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*psv.TDY_INTINCEXP else psv.TDY_INTINCEXP end as tdyIntincexp, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) else (NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) end as marketValue from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null where 1=1
AND psv.PORTFOLIO_ID IN
#{item}
and to_char(psv.CDATE,'yyyy-mm-dd') = #{searchDate}
AND fpt.TYPE_8 IN
#{item}
group by psv.CDATE,fpt.TYPE_8, fpt.TYPE_6, psv.DSC_COST_AMT, fpt.TYPE_7, psv.TDY_INTINCEXP, psv.TDY_FLOAT_INGPL )A left join ( select psv.CDATE as cdate, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) else (nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) end ) as typeMarketValue from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null where 1=1
AND psv.PORTFOLIO_ID IN
#{item}
and to_char(psv.CDATE,'yyyy-mm-dd')= #{searchDate}
AND fpt.TYPE_8 IN
#{item}
group by psv.CDATE )B on A.cdate=B.cdate and B.typeMarketValue!=0) AA group by AA.finprodType2 union all SELECT ass.finprodType2, sum(ass.marketValue) as marketValue, sum(ass.dscCostAmt) as dscCostAmt, NULL amtRation, NULL tdyIntincexp from
ass where ass.finprodType2 = #{cash} group by ass.finprodType2

